/**
 * The world sprite atlas.
 *
 * All the pixel art lives in a single PNG (`assets/world-atlas.png`) with a
 * JSON manifest that maps a name to its rectangle in the sheet. The runtime
 * loads the sheet once and draws sub-rectangles from it, which means one
 * HTTP request and no per-tile canvas slicing.
 *
 * The sheet is generated by `npm run build:atlas` from the CC0 source packs.
 */
import { TILE_SIZE } from '../core/constants.ts';

export interface AtlasFrame {
  x: number;
  y: number;
  w: number;
  h: number;
}

export const atlas = new Image();
export const atlasFrames: Record<string, AtlasFrame> = {};
export let atlasReady = false;

atlas.src = 'assets/world-atlas.png';

/** Frames grouped by their name prefix, e.g. `grass.0` -> `grass`. */
export const atlasGroups: Record<string, string[]> = {};

atlas.onload = async () => {
  try {
    const res = await fetch('assets/world-atlas.json');
    const manifest = await res.json() as Record<string, AtlasFrame>;
    for (const [name, frame] of Object.entries(manifest)) {
      atlasFrames[name] = frame;
      const group = name.split('.')[0];
      (atlasGroups[group] ||= []).push(name);
    }
    atlasReady = true;
  } catch (err) {
    console.error('Could not load the world atlas manifest', err);
  }
};

/**
 * Draw a named frame from the atlas.
 * The frame is drawn at its native size unless a size is given.
 */
export function drawAtlasTile(
  ctx: CanvasRenderingContext2D,
  name: string,
  dx: number,
  dy: number,
  size: number = TILE_SIZE,
): boolean {
  const f = atlasFrames[name];
  if (!f || !atlasReady) return false;
  ctx.drawImage(atlas, f.x, f.y, f.w, f.h, dx, dy, size, size);
  return true;
}

/** Draw a frame scaled to `w` x `h` (for props that are not tile-sized). */
export function drawAtlasTileScaled(
  ctx: CanvasRenderingContext2D,
  name: string,
  dx: number,
  dy: number,
  w: number,
  h: number,
): boolean {
  const f = atlasFrames[name];
  if (!f || !atlasReady) return false;
  ctx.drawImage(atlas, f.x, f.y, f.w, f.h, dx, dy, w, h);
  return true;
}

/**
 * Pick a deterministic variant for a tile, so the terrain looks varied but
 * never flickers between frames.
 */
export function variant(group: string, x: number, y: number, salt = 0): string | null {
  const names = atlasGroups[group];
  if (!names || names.length === 0) return null;
  const i = Math.abs((x * 7 + y * 13 + x * y * 3 + salt * 29)) % names.length;
  return names[i];
}
